no('length-case','strings','function run(): int { const text: string = "abc"; return text.Length; }','COPE-STRING-0001','Length','.length')
no('unknown-receiver','diagnostics','function run(): int { return Missing.Case(); }','COPE-BIND-0001','Missing','Undefined name')
no('array-push','collections','function run(): int { const values: int[] = [1]; values.push(2); return 0; }','COPE-CALL-0021','push','MutableArray<T>(length)')
